css:
/* ==========================================================================
   DUSTWIRE  (slug: wasteland)  by kolache
   One idea: after the fall, everything hangs on the wire. Messages, the
   message box, chat rows and dialogs are salvage TAGS (a tapered head with a
   punched eyelet) tied to a twisted wire; Home widgets are SIGNS hung from a
   clothesline; the top bar is a strip of riveted scrap with the line under it.
   ========================================================================== */

/* ---------- 1. Tokens shared by day and night ---------------------------- */
:root {
  --mari-tokens-version: 1;
  --radius: 2px;

  --dw-font-stencil: "Big Shoulders Stencil Display", "Barlow Semi Condensed", Impact, sans-serif;
  --dw-font-read: "Bitter", Georgia, serif;
  --dw-font-ui: "Barlow Semi Condensed", "Arial Narrow", system-ui, sans-serif;
  --dw-font-stamp: "Special Elite", "Courier New", monospace;

  --mari-font-ui: var(--dw-font-ui);
  --mari-font-heading: var(--dw-font-stencil);
  --mari-font-chat: var(--dw-font-read);

  --mari-selected-tint: var(--primary);
  --mari-text-outline: 0;
  --mari-chat-font-size: 16.5px;
  --mari-chat-line-height: 1.65;
  --mari-message-measure: 68ch;
  --mari-chat-column: 56rem;
  --mari-dialogue-weight: 500;
  --mari-paragraph-gap: 0.8em;
  --mari-msg-head-rule: 1px dashed color-mix(in srgb, currentColor 35%, transparent);
  --mari-min-ui-text: 12px;
  --mari-composer-placeholder: "Write on the tag...";

  --mari-app-backdrop-position: center bottom;
  --mari-chat-wash: none;
  --mari-chat-header-bg: none;
  --mari-chat-row-art-opacity: 0;
  --mari-home-art: none;
  --mari-home-widget-radius: 2px;
  --mari-home-widget-border-width: 0;
  --mari-home-widget-font: var(--dw-font-ui);
  --mari-home-widget-title-font: var(--dw-font-stencil);
  --mari-home-widget-title-size: 1.6rem;
  --mari-home-widget-eyebrow-size: 0.8rem;
  --mari-home-widget-text-size: 0.95rem;
  --mari-home-widget-action-size: 0.9rem;
  --mari-home-widget-glow: none;
  --mari-top-bar-plate-radius: 0;
  --mari-top-bar-rendering: auto;
  --mari-pinned-speaker: on;
  --mari-pinned-speaker-bg: var(--dw-tag);
  --mari-phone-avatar: hidden;

  /* tag geometry */
  --dw-cut: 1.15rem;          /* chamfer of the tag head */
  --dw-eye-x: 1.05rem;        /* eyelet centre from the head edge */
  --dw-eye-y: 1.55rem;        /* eyelet centre from the top */
  --dw-flag: #e4652a;         /* flagging tape */
  --dw-flag-2: #c24f1c;
}

/* ---------- 2. Day: sun-bleached ---------------------------------------- */
:root,
:root[data-theme="light"] {
  --background: #e9dfc9;
  --foreground: #2a2016;
  --card: color-mix(in srgb, #ece0c2 92%, transparent);
  --card-foreground: #2a2016;
  --popover: #efe4c8;
  --popover-foreground: #2a2016;
  --primary: #a63d14;
  --primary-foreground: #fff6e8;
  --secondary: #ddcca4;
  --secondary-foreground: #2a2016;
  --muted: #dccaa2;
  --muted-foreground: #5a4733;
  --accent: #d3bf92;
  --accent-foreground: #2a2016;
  --destructive: #9b2a17;
  --destructive-foreground: #fff6e8;
  --border: color-mix(in srgb, #6d5638 45%, transparent);
  --input: #f3ead4;
  --ring: #a63d14;
  --sidebar: color-mix(in srgb, #d9cdb3 90%, transparent);
  --sidebar-foreground: #241c13;
  --sidebar-border: color-mix(in srgb, #6d5638 40%, transparent);
  --sidebar-accent: #cbbb96;
  --sidebar-accent-foreground: #241c13;

  --ov-line: color-mix(in srgb, #6d5638 38%, transparent);
  --ov-text: #2a2016;
  --ov-muted: #5a4733;
  --ov-dim: #6e5a43;
  --ov-mode-conversation: #2f6b64;
  --ov-mode-roleplay: #a63d14;
  --ov-mode-game: #7a5a0e;
  --mari-mode-conversation: #2f6b64;
  --mari-mode-roleplay: #a63d14;
  --mari-mode-game: #7a5a0e;
  --mari-home-pink: #9b3f2a;
  --mari-home-violet: #5b4e78;
  --mari-chrome-accent: #a63d14;
  --mari-chrome-muted: #5a4733;
  --mari-gauge-ok: #4f7a3a;
  --mari-gauge-warn: #b07a12;
  --mari-gauge-danger: #a3271a;
  --mari-status-online: #4f7a3a;

  --dw-ink: #2a2016;
  --dw-ink-soft: #57452f;
  --dw-tag: #e3cfa0;
  --dw-tag-user: #cfd3cc;
  --dw-tag-edge: #b99a66;
  --dw-hole: #6f5f48;
  --dw-ring: #b08d4a;
  --dw-tag-img: url("theme:tag-d.webp");
  --dw-user-img: url("theme:user-d.webp");
  --dw-metal-img: url("theme:metal-d.webp");
  --dw-wire-v: url("theme:wire-v.webp");
  --dw-wire-h: url("theme:wire-h.webp");
  --dw-name: #8e3510;
  --dw-plate: color-mix(in srgb, #e9dfc9 90%, transparent);
  --dw-shadow: rgba(60, 40, 15, 0.35);

  --mari-app-backdrop: url("theme:bg-day.webp");
  --mari-page-veil: color-mix(in srgb, #e9dfc9 78%, transparent);
  --mari-home-wash: transparent;
  --mari-scrim: rgba(52, 38, 20, 0.45);
  --mari-top-bar-plate: color-mix(in srgb, #efe5cf 90%, transparent);
  --mari-top-bar-plate-active: #f6e2c7;
  --mari-dialogue-color: #7a2a0a;
  --mari-message-time: #5a4733;
  --mari-message-actions: #5a4733;
  --mari-swipe-counter: #5a4733;
}

/* ---------- 3. Night: moonlit, campfire --------------------------------- */
:root[data-theme="dark"] {
  --background: #101116;
  --foreground: #ece2cc;
  --card: color-mix(in srgb, #27221c 93%, transparent);
  --card-foreground: #ece2cc;
  --popover: #221e19;
  --popover-foreground: #ece2cc;
  --primary: #ff8a3d;
  --primary-foreground: #1c0f05;
  --secondary: #2e2923;
  --secondary-foreground: #ece2cc;
  --muted: #26221d;
  --muted-foreground: #bcae94;
  --accent: #3a3128;
  --accent-foreground: #ece2cc;
  --destructive: #e0563a;
  --destructive-foreground: #1c0f05;
  --border: color-mix(in srgb, #b49a74 30%, transparent);
  --input: #1b1915;
  --ring: #ff8a3d;
  --sidebar: color-mix(in srgb, #16161b 90%, transparent);
  --sidebar-foreground: #e6dcc6;
  --sidebar-border: color-mix(in srgb, #b49a74 22%, transparent);
  --sidebar-accent: #2b2722;
  --sidebar-accent-foreground: #ece2cc;

  --ov-line: color-mix(in srgb, #b49a74 24%, transparent);
  --ov-text: #ece2cc;
  --ov-muted: #bcae94;
  --ov-dim: #9c8f78;
  --ov-mode-conversation: #6fb3a8;
  --ov-mode-roleplay: #ff8a3d;
  --ov-mode-game: #e3c45a;
  --mari-mode-conversation: #6fb3a8;
  --mari-mode-roleplay: #ff8a3d;
  --mari-mode-game: #e3c45a;
  --mari-home-pink: #e88a6e;
  --mari-home-violet: #a99ad0;
  --mari-chrome-accent: #ff8a3d;
  --mari-chrome-muted: #bcae94;
  --mari-gauge-ok: #8fbf6a;
  --mari-gauge-warn: #e3b04a;
  --mari-gauge-danger: #f0603e;
  --mari-status-online: #8fbf6a;

  --dw-ink: #ece2cc;
  --dw-ink-soft: #c4b59a;
  --dw-tag: #29241d;
  --dw-tag-user: #23262a;
  --dw-tag-edge: #5c4c38;
  --dw-hole: #0b0c10;
  --dw-ring: #8a6c3a;
  --dw-tag-img: url("theme:tag-n.webp");
  --dw-user-img: url("theme:user-n.webp");
  --dw-metal-img: url("theme:metal-n.webp");
  --dw-wire-v: url("theme:wire-v-n.webp");
  --dw-wire-h: url("theme:wire-h-n.webp");
  --dw-name: #ffa266;
  --dw-plate: color-mix(in srgb, #15151a 88%, transparent);
  --dw-shadow: rgba(0, 0, 0, 0.6);

  --mari-app-backdrop: url("theme:bg-night.webp");
  --mari-page-veil: color-mix(in srgb, #101116 80%, transparent);
  --mari-scrim: rgba(5, 5, 8, 0.6);
  --mari-top-bar-plate: color-mix(in srgb, #17161a 88%, transparent);
  --mari-top-bar-plate-active: #3a2a1e;
  --mari-dialogue-color: #ecb98c;
  --mari-message-time: #bcae94;
  --mari-message-actions: #bcae94;
  --mari-swipe-counter: #bcae94;
}

/* ---------- 4. Top bar: a strip of riveted scrap, the main wire under it -- */
:root {
  --mari-top-bar-bg:
    var(--dw-wire-h) left bottom 1px / 240px 7px repeat-x,
    linear-gradient(to bottom, transparent calc(100% - 9px), var(--dw-topbar-foot) calc(100% - 9px)),
    url("theme:topbar.webp") center 40% / 100% auto no-repeat,
    #8f8a7e;
  --dw-topbar-foot: color-mix(in srgb, #e9dfc9 75%, transparent);
}
:root[data-theme="dark"] {
  --dw-topbar-foot: color-mix(in srgb, #101116 75%, transparent);
  --mari-top-bar-bg:
    var(--dw-wire-h) left bottom 1px / 240px 7px repeat-x,
    linear-gradient(to bottom, transparent calc(100% - 9px), var(--dw-topbar-foot) calc(100% - 9px)),
    linear-gradient(rgba(8, 8, 12, 0.58), rgba(8, 8, 12, 0.58)),
    url("theme:topbar.webp") center 40% / 100% auto no-repeat,
    #2a2925;
}
[data-component="TopBar"] {
  padding-bottom: 9px;
  border-bottom: 0;
}
[data-component="TopBar"] .ov-tab,
[data-component="TopBar"] .ov-text-btn {
  font-family: var(--dw-font-stencil);
  font-weight: 800;
  font-size: 1.02rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
[data-component="TopBar"] .ov-text-btn small {
  font-family: var(--dw-font-ui);
  text-transform: none;
  letter-spacing: 0;
  font-weight: 500;
}

/* ---------- 5. Surfaces: galvanised sheet sidebars, veiled pages ---------- */
[data-component="ChatSidebar"],
[data-component="RightPanelDesktop"] {
  background:
    linear-gradient(var(--dw-panel-wash), var(--dw-panel-wash)),
    var(--dw-metal-img) 0 0 / 512px repeat !important;
}
:root {
  --dw-panel-wash: color-mix(in srgb, #e3dac6 35%, transparent);
}
:root[data-theme="dark"] {
  --dw-panel-wash: color-mix(in srgb, #0d0d11 30%, transparent);
}
[data-component="ChatSidebar"] .mari-sidebar-header,
[data-component="OverhaulLibraryNav"] h2,
[data-component="OverhaulLibraryPage"] h1,
[data-component="OverhaulSettingsPage"] h1 {
  font-family: var(--dw-font-stencil);
  letter-spacing: 0.04em;
}
[data-component="ChatSidebar"] .mari-sidebar-header span {
  font-family: var(--dw-font-stencil);
  font-weight: 800;
  font-size: 1.15rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

/* ---------- 6. Roleplay: tags tied to a drop wire ----------------------- */
.mari-roleplay-message-row {
  position: relative;
  margin-bottom: 1.35rem;
}
/* the wire runs through the avatar column; the avatar is a washer on it */
.mari-roleplay-message-row > [data-mari-part="avatar"] {
  position: relative;
  align-self: stretch;
}
.mari-roleplay-message-row > [data-mari-part="avatar"]::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: -1.35rem;
  left: calc(50% - 3.5px);
  width: 7px;
  background: var(--dw-wire-v) center top / 7px 240px repeat-y;
  z-index: 0;
  pointer-events: none;
}
.mari-roleplay-message-row > [data-mari-part="avatar"] > * {
  position: relative;
  z-index: 1;
}
.mari-roleplay-message-row [data-mari-part="avatar"] button {
  border-radius: 999px;
  box-shadow:
    0 0 0 3px var(--dw-ring),
    0 0 0 5px color-mix(in srgb, var(--dw-hole) 80%, transparent),
    0 3px 6px var(--dw-shadow);
}

/* the tag itself: tapered head on the wire side, eyelet punched through */
.mari-roleplay-message-row .mari-message-body {
  filter: drop-shadow(0 3px 4px var(--dw-shadow));
}
.mari-rp-bubble {
  border-radius: 0 !important;
  box-shadow: none !important;
  --tw-ring-shadow: 0 0 #0000 !important;
  color: var(--dw-ink) !important;
  background:
    radial-gradient(circle at var(--dw-eye-x) var(--dw-eye-y), var(--dw-hole) 0 4.5px, var(--dw-ring) 7px 240px, color-mix(in srgb, var(--dw-ring) 40%, transparent) 8.5px 9px, transparent 9.5px),
    linear-gradient(90deg, color-mix(in srgb, var(--dw-tag-edge) 38%, transparent) 0 2.15rem, transparent 2.15rem),
    var(--dw-tag-img) 0 0 / 512px repeat,
    var(--dw-tag) !important;
  clip-path: polygon(var(--dw-cut) 0, 100% 0, 100% 100%, var(--dw-cut) 100%, 0 calc(100% - var(--dw-cut)), 0 var(--dw-cut));
  opacity: 1 !important;
}
.mari-rp-bubble > div {
  padding: 0.85rem 1.5rem 1.1rem 2.85rem !important;
}
/* your own replies: a grey survey tag hung the other way */
.mari-rp-bubble.mari-rp-bubble--user {
  background:
    radial-gradient(circle at calc(100% - var(--dw-eye-x)) var(--dw-eye-y), var(--dw-hole) 0 4.5px, var(--dw-ring) 7px 240px, color-mix(in srgb, var(--dw-ring) 40%, transparent) 8.5px 9px, transparent 9.5px),
    linear-gradient(270deg, color-mix(in srgb, var(--dw-tag-edge) 32%, transparent) 0 2.15rem, transparent 2.15rem),
    var(--dw-user-img) 0 0 / 512px repeat,
    var(--dw-tag-user) !important;
  clip-path: polygon(0 0, calc(100% - var(--dw-cut)) 0, 100% var(--dw-cut), 100% calc(100% - var(--dw-cut)), calc(100% - var(--dw-cut)) 100%, 0 100%);
}
.mari-rp-bubble.mari-rp-bubble--user > div {
  padding: 0.85rem 2.85rem 1.1rem 1.5rem !important;
}

/* the short tie from the eyelet to the drop wire */
.mari-roleplay-message-row .mari-message-body::before {
  content: "";
  position: absolute;
  top: calc(var(--dw-eye-y) - 3.5px);
  left: -2.05rem;
  width: calc(2.05rem + var(--dw-eye-x));
  height: 7px;
  background: var(--dw-wire-h) left center / 240px 7px repeat-x;
  z-index: 2;
  pointer-events: none;
}
.mari-message-user.mari-roleplay-message-row .mari-message-body::before {
  left: auto;
  right: -2.05rem;
}
/* the newest reply wears a strip of flagging tape at its eyelet */
[data-mari-part="message"][data-latest].mari-roleplay-message-row .mari-message-body::after {
  content: "";
  position: absolute;
  top: calc(var(--dw-eye-y) + 2px);
  left: -0.85rem;
  width: 0.7rem;
  height: 2.6rem;
  background:
    repeating-linear-gradient(180deg, transparent 0 7px, rgba(0, 0, 0, 0.08) 7px 8px),
    linear-gradient(90deg, var(--dw-flag), var(--dw-flag-2));
  clip-path: polygon(0 0, 100% 0, 100% 100%, 50% 85%, 0 100%);
  transform: rotate(8deg);
  transform-origin: top center;
  z-index: 3;
  pointer-events: none;
}

/* name line: spray stencil; the time is stamped with a lot number */
.mari-rp-bubble .mari-message-name {
  font-family: var(--dw-font-stencil);
  font-size: 1.25rem !important;
  font-weight: 800 !important;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--dw-name) !important;
}
.mari-rp-bubble [data-mari-part="time"],
.mari-message [data-mari-part="time"] {
  font-family: var(--dw-font-stamp);
  font-size: 0.8rem !important;
  color: var(--dw-ink-soft) !important;
}
.mari-rp-bubble [data-mari-part="time"]::before {
  counter-reset: lot var(--mari-msg-index);
  content: "No." counter(lot) "  ";
}
.mari-rp-bubble .mari-message-content {
  color: var(--dw-ink);
  max-width: var(--mari-message-measure);
}
.mari-rp-bubble .ov-rpf__btn,
.mari-roleplay-message-row .ov-rpf__btn,
.mari-roleplay-message-row .ov-rpf__swipes {
  color: var(--dw-ink-soft);
}
.mari-roleplay-message-row .ov-rpf--below {
  color: var(--foreground);
}

/* ---------- 7. Message box: the blank tag being written ----------------- */
[data-mari-part="composer"] .mari-chat-input-box {
  border-radius: 0 !important;
  border: 0 !important;
  --tw-ring-shadow: 0 0 #0000 !important;
  box-shadow: none !important;
  background:
    radial-gradient(circle at 1.05rem 50%, var(--dw-hole) 0 4.5px, var(--dw-ring) 7px 240px, transparent 8.5px),
    linear-gradient(90deg, color-mix(in srgb, var(--dw-tag-edge) 38%, transparent) 0 2.15rem, transparent 2.15rem),
    var(--dw-tag-img) 0 0 / 512px repeat,
    var(--dw-tag) !important;
  color: var(--dw-ink) !important;
  clip-path: polygon(var(--dw-cut) 0, 100% 0, 100% 100%, var(--dw-cut) 100%, 0 calc(100% - var(--dw-cut)), 0 var(--dw-cut));
  padding-left: 2.6rem !important;
  backdrop-filter: none !important;
}
[data-mari-part="composer"] {
  filter: drop-shadow(0 3px 5px var(--dw-shadow));
}
[data-mari-part="composer"] textarea {
  font-family: var(--dw-font-read);
  font-size: 15.5px !important;
  color: var(--dw-ink) !important;
}
[data-mari-part="composer"] textarea::placeholder {
  font-family: var(--dw-font-stamp);
  color: var(--dw-ink-soft) !important;
  opacity: 1;
}
[data-mari-part="composer"] button {
  color: var(--dw-ink-soft) !important;
}
[data-mari-part="composer"] .mari-chat-send-btn {
  color: var(--dw-name) !important;
}

/* ---------- 8. Conversation: slim tags on one wire ---------------------- */
[data-chat-mode="conversation"] [data-mari-part="message"] {
  position: relative;
}
[data-chat-mode="conversation"] [data-mari-part="message"]::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: calc(1rem + 1.25rem - 3.5px);
  width: 7px;
  background: var(--dw-wire-v) center top / 7px 240px repeat-y;
  pointer-events: none;
  z-index: 0;
}
[data-chat-mode="conversation"] .mari-message {
  background: transparent !important;
}
[data-chat-mode="conversation"] .mari-message [data-mari-part="avatar"] {
  position: relative;
  z-index: 1;
}
[data-chat-mode="conversation"] .mari-message [data-mari-part="avatar"] button {
  box-shadow: 0 0 0 3px var(--dw-ring), 0 2px 5px var(--dw-shadow);
}
[data-chat-mode="conversation"] .mari-message .mari-message-body {
  flex: 0 1 auto;
  max-width: min(46rem, 100%);
  margin: 0.2rem 0;
  padding: 0.45rem 1.1rem 0.55rem 2.1rem;
  color: var(--dw-ink);
  background:
    radial-gradient(circle at 0.9rem 1.05rem, var(--dw-hole) 0 3.5px, var(--dw-ring) 4px 6.5px, transparent 7px),
    var(--dw-tag-img) 0 0 / 512px repeat,
    var(--dw-tag);
  clip-path: polygon(0.8rem 0, 100% 0, 100% 100%, 0.8rem 100%, 0 calc(100% - 0.8rem), 0 0.8rem);
}
[data-chat-mode="conversation"] .mari-message-user .mari-message-body,
[data-chat-mode="conversation"] [data-message-role="user"] .mari-message-body {
  background:
    radial-gradient(circle at 0.9rem 1.05rem, var(--dw-hole) 0 3.5px, var(--dw-ring) 4px 6.5px, transparent 7px),
    var(--dw-user-img) 0 0 / 512px repeat,
    var(--dw-tag-user);
}
[data-chat-mode="conversation"] .mari-message .mari-message-name {
  font-family: var(--dw-font-stencil);
  font-weight: 800;
  font-size: 1.1rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--dw-name) !important;
}
[data-chat-mode="conversation"] .mari-message .mari-message-content {
  color: var(--dw-ink) !important;
}
[data-chat-mode="conversation"] .mari-message .mari-message-content * {
  color: inherit;
}
[data-mari-part="chat-header"] button {
  border-radius: 0 !important;
  background: var(--dw-tag-img) 0 0 / 512px, var(--dw-tag) !important;
  color: var(--dw-ink) !important;
  clip-path: polygon(0.6rem 0, 100% 0, 100% 100%, 0.6rem 100%, 0 calc(100% - 0.6rem), 0 0.6rem);
  padding-left: 0.9rem !important;
}
[data-mari-part="chat-header"] button span {
  color: var(--dw-ink) !important;
}

/* ---------- 9. Chats sidebar: rows are tags threaded on a wire ---------- */
[data-component="ChatSidebar"] .stagger-children {
  position: relative;
  padding-left: 1.2rem !important;
}
[data-component="ChatSidebar"] .stagger-children::before {
  content: "";
  position: absolute;
  top: -0.5rem;
  bottom: 0;
  left: 0.35rem;
  width: 7px;
  background: var(--dw-wire-v) center top / 7px 240px repeat-y;
  pointer-events: none;
}
[data-chat-row] {
  border-radius: 0 !important;
  clip-path: polygon(0.7rem 0, 100% 0, 100% 100%, 0.7rem 100%, 0 calc(100% - 0.7rem), 0 0.7rem);
  padding-left: 1.5rem !important;
  background:
    radial-gradient(circle at 0.62rem 50%, var(--dw-hole) 0 3px, var(--dw-ring) 3.5px 5.5px, transparent 6px),
    linear-gradient(color-mix(in srgb, var(--dw-tag) 30%, transparent), color-mix(in srgb, var(--dw-tag) 30%, transparent)),
    var(--dw-tag-img) 0 0 / 512px !important;
  --tw-ring-shadow: 0 0 #0000 !important;
  box-shadow: none !important;
  margin-bottom: 0.35rem;
  color: var(--dw-ink);
}
[data-chat-row]:not([data-selected="true"]) {
  opacity: 0.94;
}
[data-chat-row]:hover {
  opacity: 1;
}
[data-chat-row][data-selected="true"] {
  background:
    radial-gradient(circle at 0.62rem 50%, var(--dw-hole) 0 3px, var(--dw-flag) 3.5px 5.5px, transparent 6px),
    linear-gradient(90deg, transparent calc(100% - 4px), var(--dw-flag) calc(100% - 4px)),
    var(--dw-tag-img) 0 0 / 512px,
    var(--dw-tag) !important;
  transform: translateX(0.35rem);
}
[data-chat-row] .mari-chrome-accent-progress {
  display: none;
}
[data-chat-row] span.block.truncate {
  font-weight: 600;
  font-size: 0.98rem;
  color: var(--dw-ink) !important;
}
[data-chat-row] .tabular-nums {
  font-family: var(--dw-font-stamp);
  color: var(--dw-ink-soft) !important;
  font-size: 0.72rem;
}
[data-chat-row] img,
[data-chat-row] [data-mari-part="avatar-placeholder"] {
  border-radius: 999px;
}
[data-chat-row] span.rounded-lg {
  border-radius: 999px !important;
  box-shadow: 0 0 0 2px var(--dw-ring);
}

/* ---------- 10. Home: salvage on the line, then a clothesline of signs --- */
[data-component="HomeBrowserHub.HomePage"] {
  background: transparent !important;
}
.mari-home-browser-starfield {
  display: none;
}
.mari-home-hero {
  padding-top: 196px !important;
  background: url("theme:hero-tags.webp") center top / auto 190px no-repeat;
}
:root[data-theme="dark"] .mari-home-hero {
  background-image: url("theme:hero-tags-night.webp");
}
.mari-home-hero h1 {
  font-family: var(--dw-font-stencil);
  font-weight: 800 !important;
  font-size: clamp(1.6rem, 2.4vw, 2.4rem) !important;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: var(--dw-ink);
  text-shadow: 0 1px 0 var(--dw-plate), 0 0 14px var(--dw-plate);
}
.mari-home-widget {
  position: relative;
  padding-top: 0.95rem;
}
.mari-home-widget::after {
  content: "";
  position: absolute;
  top: 0.05rem;
  left: -0.8rem;
  right: -0.8rem;
  height: 1.7rem;
  background:
    var(--dw-wire-h) left top / 240px 7px repeat-x,
    var(--dw-wire-v) 1.3rem 3px / 7px 240px no-repeat,
    var(--dw-wire-v) 1.3rem 11px / 7px 240px no-repeat,
    var(--dw-wire-v) 1.3rem 19px / 7px 240px no-repeat,
    var(--dw-wire-v) calc(100% - 1.3rem) 3px / 7px 240px no-repeat,
    var(--dw-wire-v) calc(100% - 1.3rem) 11px / 7px 240px no-repeat,
    var(--dw-wire-v) calc(100% - 1.3rem) 19px / 7px 240px no-repeat;
  background-origin: content-box;
  padding: 0 0.8rem;
  pointer-events: none;
  z-index: 3;
}
[data-mari-part="home-widget"] {
  border: 0 !important;
  border-radius: 0 !important;
  background:
    radial-gradient(circle at 1.45rem 1.25rem, var(--dw-hole) 0 4px, var(--dw-ring) 4.5px 7px, transparent 7.5px),
    radial-gradient(circle at calc(100% - 1.45rem) 1.25rem, var(--dw-hole) 0 4px, var(--dw-ring) 4.5px 7px, transparent 7.5px),
    var(--dw-tag-img) 0 0 / 512px repeat,
    var(--dw-tag) !important;
  clip-path: polygon(1rem 0, calc(100% - 1rem) 0, 100% 1rem, 100% 100%, 0 100%, 0 1rem);
  color: var(--dw-ink);
  --mari-home-widget-title-color: var(--dw-ink);
  --mari-home-widget-muted: var(--dw-ink-soft);
  --mari-home-widget-eyebrow-color: var(--dw-name);
  --foreground: var(--dw-ink);
  --muted-foreground: var(--dw-ink-soft);
  padding-top: 1.9rem !important;
  box-shadow: none !important;
}
[data-mari-part="home-widget-title"] {
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-weight: 800 !important;
}
[data-mari-part="home-widget-eyebrow"] {
  font-family: var(--dw-font-stamp);
  font-weight: 400 !important;
  letter-spacing: 0.12em;
  color: var(--dw-name) !important;
}

/* ---------- 11. Game: the narration is a sign hung on two wires --------- */
:root {
  --mari-stage-empty-bg: url("theme:bg-haze-day.webp") center / cover;
}
:root[data-theme="dark"] {
  --mari-stage-empty-bg: url("theme:bg-haze-night.webp") center / cover;
}
[data-mari-part="message"][data-game-narration] {
  position: relative;
  overflow: visible !important;
  border: 0 !important;
  border-radius: 0 !important;
  backdrop-filter: none !important;
  color: var(--dw-ink);
  background:
    radial-gradient(circle at 1.3rem 1.1rem, var(--dw-hole) 0 4px, var(--dw-ring) 4.5px 7px, transparent 7.5px),
    radial-gradient(circle at calc(100% - 1.3rem) 1.1rem, var(--dw-hole) 0 4px, var(--dw-ring) 4.5px 7px, transparent 7.5px),
    var(--dw-tag-img) 0 0 / 512px repeat,
    var(--dw-tag) !important;
  padding-top: 2rem !important;
  --foreground: var(--dw-ink);
  --muted-foreground: var(--dw-ink-soft);
}
[data-mari-part="message"][data-game-narration]::before {
  content: "";
  position: absolute;
  bottom: calc(100% - 1.1rem);
  height: 2.4rem;
  left: calc(1.3rem - 3.5px);
  right: calc(1.3rem - 3.5px);
  background:
    var(--dw-wire-v) left bottom / 7px 240px repeat-y,
    var(--dw-wire-v) right bottom / 7px 240px repeat-y;
  pointer-events: none;
}
[data-mari-part="message"][data-game-narration] .game-narration-prose {
  background: transparent !important;
  border: 1px dashed color-mix(in srgb, var(--dw-ink) 30%, transparent) !important;
  border-radius: 0 !important;
  color: var(--dw-ink) !important;
  font-family: var(--dw-font-read);
}
[data-mari-part="message"][data-game-narration] .game-narration-prose * {
  color: inherit;
}
[data-mari-part="message"][data-game-narration] > div:first-child span {
  font-family: var(--dw-font-stencil);
  font-size: 0.95rem;
  letter-spacing: 0.1em;
  background: transparent !important;
  color: var(--dw-name) !important;
}
[data-mari-part="game-tools"] button,
[data-mari-part="message"][data-game-narration] button {
  border-radius: 0 !important;
  color: var(--dw-ink) !important;
  border-color: color-mix(in srgb, var(--dw-ink) 35%, transparent) !important;
  background: color-mix(in srgb, var(--dw-tag) 70%, var(--dw-ink) 6%) !important;
}
[data-mari-part="game-hud"] > * {
  border-radius: 0 !important;
  background: var(--dw-tag-img) 0 0 / 512px, var(--dw-tag) !important;
  color: var(--dw-ink) !important;
  border-color: var(--dw-tag-edge) !important;
}

/* ---------- 12. Ctrl+K, windows and dialogs: big shipping tags --------- */
.mari-window,
[role="dialog"] {
  border-radius: 0 !important;
  --dw-sheet: var(--dw-tag);
}
[data-component="GlobalOmnibar"] > div {
  background:
    radial-gradient(circle at 50% 1.1rem, var(--dw-hole) 0 5px, var(--dw-ring) 5.5px 9px, transparent 9.5px),
    var(--dw-tag-img) 0 0 / 512px repeat,
    var(--dw-tag) !important;
  clip-path: polygon(1.4rem 0, calc(100% - 1.4rem) 0, 100% 1.4rem, 100% 100%, 0 100%, 0 1.4rem);
  padding-top: 1.4rem;
  --card: var(--dw-tag);
  --foreground: var(--dw-ink);
  --muted-foreground: var(--dw-ink-soft);
  color: var(--dw-ink);
}
[data-component="GlobalOmnibar"] > div > div:first-child {
  display: none;
}
.mari-window {
  background:
    var(--dw-tag-img) 0 0 / 512px repeat,
    var(--dw-tag) !important;
  --background: var(--dw-tag);
  --foreground: var(--dw-ink);
  --muted-foreground: var(--dw-ink-soft);
  color: var(--dw-ink);
  border: 1px solid var(--dw-tag-edge) !important;
  box-shadow: 0 10px 30px var(--dw-shadow) !important;
}

/* ---------- 13. Controls: stencilled plates, square corners ------------- */
.mari-chrome-control,
.mari-chrome-segmented,
.mari-chrome-segmented > *,
.ov-home-modes > *,
.ov-home-hero-actions > * {
  border-radius: 0 !important;
}
.mari-chrome-control--primary,
.mari-chrome-control--selected {
  font-weight: 700;
}
.ov-home-modes button,
.ov-home-hero-actions button {
  font-family: var(--dw-font-stencil);
  font-weight: 800 !important;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  font-size: 0.98rem !important;
  background: var(--dw-plate) !important;
}

/* ---------- 14. Library cards: tags with a punched eyelet --------------- */
:root {
  --mari-card-art-placeholder:
    radial-gradient(circle at 50% 1rem, var(--dw-hole) 0 5px, var(--dw-ring) 5.5px 8.5px, transparent 9px),
    linear-gradient(160deg, color-mix(in srgb, var(--dw-tag-edge) 70%, transparent), transparent 60%),
    var(--dw-tag-img) 0 0 / 512px,
    var(--dw-tag);
  --mari-art-saturation-1: 22%;
  --mari-art-lightness-1: 58%;
  --mari-art-saturation-2: 18%;
  --mari-art-lightness-2: 40%;
}
[data-mari-part="card-art"] {
  border-radius: 0 !important;
  clip-path: polygon(1rem 0, calc(100% - 1rem) 0, 100% 1rem, 100% 100%, 0 100%, 0 1rem);
}

/* ---------- 15. Weather: dust, acid rain, ash winter, dry lightning ------ */
:root {
  --mari-weather-sand-color: #8a6532;
  --mari-weather-sand-size: 1.3;
  --mari-weather-rain-color: #eef2b4;
  --mari-weather-rain-length: 1.1;
  --mari-weather-strength: 1.3;
  --mari-weather-snow-color: #6f6b64;
  --mari-weather-snow-shape: square;
  --mari-weather-snow-size: 1.1;
  --mari-weather-ash-color: #7d7a74;
  --mari-weather-fog-color: #dcc68c;
  --mari-weather-dust-color: #b99a62;
  --mari-weather-ember-color: #ff8a3d;
  --mari-weather-leaf-image: url("theme:wx-scrap-1.webp") url("theme:wx-scrap-2.webp") url("theme:wx-scrap-3.webp");
  --mari-weather-leaf-size: 0.9;
  --mari-weather-lightning-color: #ffe6b8;
  --mari-weather-lightning-bolt: 2.2;
  --mari-weather-tint-strength: 0.45;
  --mari-weather-sun: none;
}
:root[data-theme="dark"] {
  --mari-weather-rain-color: #d2db86;
  --mari-weather-sand-color: #c9a46a;
  --mari-weather-snow-color: #bdb9b1;
  --mari-weather-ash-color: #9a968e;
  --mari-weather-fog-color: #6a5c43;
  --mari-weather-dust-color: #c9b48a;
  --mari-weather-moon: none;
  --mari-weather-star-color: #d9dbe8;
  --mari-weather-lightning-color: #ffd9a0;
}

/* ---------- 16. Weather-aware and phone backdrops ----------------------- */
:root[data-theme="light"]:is([data-mari-weather="rain"], [data-mari-weather="storm"], [data-mari-weather="fog"], [data-mari-weather="sand"], [data-mari-weather="hail"], [data-mari-weather="cloudy"]) {
  --mari-app-backdrop: url("theme:bg-haze-day.webp");
}
:root[data-theme="dark"]:is([data-mari-weather="rain"], [data-mari-weather="storm"], [data-mari-weather="fog"], [data-mari-weather="sand"], [data-mari-weather="hail"], [data-mari-weather="cloudy"]) {
  --mari-app-backdrop: url("theme:bg-haze-night.webp");
}
:root[data-theme="light"]:is([data-mari-weather="snow"], [data-mari-weather="ash"]) {
  --mari-app-backdrop: url("theme:bg-ash-day.webp");
}
:root[data-theme="dark"]:is([data-mari-weather="snow"], [data-mari-weather="ash"]) {
  --mari-app-backdrop: url("theme:bg-ash-night.webp");
}
@media (max-width: 760px) and (orientation: portrait) {
  :root[data-theme="light"] { --mari-app-backdrop: url("theme:bg-phone-day.webp"); }
  :root[data-theme="dark"] { --mari-app-backdrop: url("theme:bg-phone-night.webp"); }
}

/* ---------- 17. Small fixes -------------------------------------------- */
[data-chat-mode="conversation"] .mari-message [data-mari-part="avatar"]::after {
  content: "";
  position: absolute;
  top: calc(50% - 3.5px);
  left: 100%;
  width: calc(1rem + 0.9rem);
  height: 7px;
  background: var(--dw-wire-h) left center / 240px 7px repeat-x;
  pointer-events: none;
}
[data-chat-mode="conversation"] .mari-message [data-mari-part="avatar"]:not(:has(button))::after {
  display: none;
}
[data-mari-part="message"][data-game-narration] .anim-text-flicker {
  color: var(--dw-name) !important;
}

/* ---------- 18. Phones: two rails down the column, tags tied to either --- */
.mari-roleplay-message-row [data-mari-part="header"][data-placement="outside"] .mari-message-name {
  font-family: var(--dw-font-stencil);
  font-size: 1.15rem !important;
  font-weight: 800 !important;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--dw-name) !important;
}
.mari-roleplay-message-row [data-mari-part="header"][data-placement="outside"] {
  background: transparent !important;
  text-shadow: 0 0 6px var(--dw-plate), 0 0 2px var(--dw-plate);
}
@media (max-width: 767px) {
  :root {
    --mari-pinned-speaker: none;
  }
  .mari-roleplay-message-row {
    padding-left: 1.35rem !important;
    padding-right: 1.35rem !important;
  }
  .mari-roleplay-message-row::before,
  .mari-roleplay-message-row::after {
    content: "";
    position: absolute;
    top: 0;
    bottom: -1.35rem;
    width: 7px;
    background: var(--dw-wire-v) center top / 7px 240px repeat-y;
    pointer-events: none;
  }
  .mari-roleplay-message-row::before { left: 0.4rem; }
  .mari-roleplay-message-row::after { right: 0.4rem; }
  .mari-roleplay-message-row .mari-message-body::before {
    left: -0.95rem;
    width: calc(0.95rem + var(--dw-eye-x));
  }
  .mari-message-user.mari-roleplay-message-row .mari-message-body::before {
    left: auto;
    right: -0.95rem;
  }
  [data-mari-part="message"][data-latest].mari-roleplay-message-row .mari-message-body::after {
    left: -0.6rem;
    width: 0.5rem;
  }
}
.mari-roleplay-message-row [data-mari-part="header"][data-placement="outside"] {
  height: 1.8rem;
  align-items: center;
  overflow: hidden;
}
.mari-roleplay-message-row .mari-message-body:has(> [data-mari-part="header"][data-placement="outside"])::before,
[data-mari-part="message"][data-latest].mari-roleplay-message-row .mari-message-body:has(> [data-mari-part="header"][data-placement="outside"])::after {
  margin-top: 1.925rem;
}

/* ---------- 19. The ground strip under the message box ----------------- */
/* Messages scroll away behind a strip of ground with the bottom wire on top,
   so no text ever shows under or beside the tag being written. */
:root { --dw-band: #ddd0b2; }
:root[data-theme="dark"] { --dw-band: #121216; }
[data-mari-part="composer"][data-composer="roleplay"],
[data-mari-part="composer"][data-composer="conversation"] {
  background:
    var(--dw-wire-h) left top / 240px 7px repeat-x,
    var(--dw-band);
  padding-top: 0.85rem !important;
  position: relative;
  z-index: 2;
}
@media (max-width: 767px) {
  .mari-rp-bubble > div {
    padding: 0.7rem 1rem 0.9rem 2.35rem !important;
  }
  .mari-rp-bubble.mari-rp-bubble--user > div {
    padding: 0.7rem 2.35rem 0.9rem 1rem !important;
  }
}
[data-mari-part="composer"][data-composer="roleplay"]::after,
[data-mari-part="composer"][data-composer="conversation"]::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 100%;
  height: 3rem;
  background: var(--dw-band);
  pointer-events: none;
}
.mari-window {
  background:
    radial-gradient(circle at 50% 0.7rem, var(--dw-hole) 0 4px, var(--dw-ring) 4.5px 7px, transparent 7.5px),
    var(--dw-tag-img) 0 0 / 512px repeat,
    var(--dw-tag) !important;
}

/* ==========================================================================
   ROUND 2: weathered tags, real wire and steel, opaque ground, no stock UI
   ========================================================================== */

/* ---------- 20. Weathering kit (baked images, no blend modes) ------------ */
:root {
  --dw-fold: #c4a674;
  --dw-fade: linear-gradient(172deg, rgba(255, 251, 238, 0.32), transparent 45%);
  --dw-stain-img: url("theme:stain-ring.webp");
  --dw-grime-img: url("theme:grime-smudge.webp");
  --dw-rust-img: url("theme:rust-bleed.webp");
  --dw-sheet-img: url("theme:sheet-d.webp");
  --dw-strip: 2.15rem;
}
:root[data-theme="dark"] {
  --dw-fold: #4d3d2a;
  --dw-rust-img: url("theme:rust-bleed-n.webp");
  --dw-grime-img: url("theme:grime-smudge-n.webp");
  --dw-stain-img: url("theme:stain-n.webp");
  --dw-sheet-img: url("theme:sheet-n.webp");
  --dw-fade: radial-gradient(ellipse 70% 120% at 0 0, rgba(255, 176, 96, 0.1), transparent 70%);
}
/* every tag gets its own wear: a ring stain, a dog-eared far corner, or neither */
/* wear is picked from the message's own index, so it varies on every layout */
[data-mari-part="message"] {
  --dw-i: var(--mari-msg-index, 1);
  --dw-stain: var(--dw-stain-img) right -2.2rem bottom -3.4rem / calc(max(0, mod(var(--dw-i) * 3, 4) - 2) * 8.5rem) auto no-repeat;
  --dw-dog: calc(max(0, mod(var(--dw-i) * 2, 3) - 1) * 1.05rem);
}

.mari-rp-bubble {
  background:
    radial-gradient(circle at var(--dw-eye-x) var(--dw-eye-y), var(--dw-hole) 0 4.5px, var(--dw-ring) 5px 8px, color-mix(in srgb, var(--dw-ring) 40%, transparent) 8.5px 9px, transparent 9.5px),
    var(--dw-rust-img) calc(var(--dw-eye-x) - var(--dw-rust-w) / 2) calc(var(--dw-eye-y) + var(--dw-rust-dy)) / var(--dw-rust-w) auto no-repeat,
    linear-gradient(45deg, var(--dw-fold) 0 47%, rgba(40, 25, 10, 0.35) 49%, transparent 51%) right top / var(--dw-dog) var(--dw-dog) no-repeat,
    var(--dw-grime-l),
    var(--dw-stain),
    var(--dw-fade),
    linear-gradient(90deg, color-mix(in srgb, var(--dw-tag-edge) 38%, transparent) 0 var(--dw-strip), transparent var(--dw-strip)),
    var(--dw-tag-img) 0 0 / 512px repeat,
    var(--dw-tag) !important;
  clip-path: polygon(var(--dw-cut) 0, calc(100% - var(--dw-dog)) 0, 100% var(--dw-dog), 100% 100%, var(--dw-cut) 100%, 0 calc(100% - var(--dw-cut)), 0 var(--dw-cut));
}
.mari-rp-bubble.mari-rp-bubble--user {
  background:
    radial-gradient(circle at calc(100% - var(--dw-eye-x)) var(--dw-eye-y), var(--dw-hole) 0 4.5px, var(--dw-ring) 5px 8px, color-mix(in srgb, var(--dw-ring) 40%, transparent) 8.5px 9px, transparent 9.5px),
    var(--dw-rust-img) right calc(var(--dw-eye-x) - var(--dw-rust-w) / 2) top calc(var(--dw-eye-y) + var(--dw-rust-dy)) / var(--dw-rust-w) auto no-repeat,
    linear-gradient(-45deg, #a9ada6 0 47%, rgba(20, 20, 20, 0.3) 49%, transparent 51%) left top / var(--dw-dog) var(--dw-dog) no-repeat,
    var(--dw-stain),
    linear-gradient(188deg, rgba(255, 255, 250, 0.2), transparent 45%),
    linear-gradient(270deg, color-mix(in srgb, var(--dw-tag-edge) 32%, transparent) 0 var(--dw-strip), transparent var(--dw-strip)),
    var(--dw-user-img) 0 0 / 512px repeat,
    var(--dw-tag-user) !important;
  clip-path: polygon(var(--dw-dog) 0, calc(100% - var(--dw-cut)) 0, 100% var(--dw-cut), 100% calc(100% - var(--dw-cut)), calc(100% - var(--dw-cut)) 100%, 0 100%, 0 var(--dw-dog));
}
:root[data-theme="dark"] .mari-rp-bubble.mari-rp-bubble--user {
  --dw-fold-u: #3a3e44;
}
.mari-message-user {
  --mari-pinned-speaker-bg: var(--dw-tag-user);
}
/* conversation tags and the composer get the same grime at the eyelet */
[data-chat-mode="conversation"] .mari-message .mari-message-body {
  background:
    radial-gradient(circle at 0.9rem 1.05rem, var(--dw-hole) 0 3.5px, var(--dw-ring) 4px 6.5px, transparent 7px),
    var(--dw-rust-img) calc(0.9rem - 4px) calc(1.05rem + 5px) / 8px auto no-repeat,
    var(--dw-grime-img) 0 0 / 6rem 3rem no-repeat,
    var(--dw-fade),
    var(--dw-tag-img) 0 0 / 512px repeat,
    var(--dw-tag);
}
[data-chat-mode="conversation"] .mari-message-user .mari-message-body,
[data-chat-mode="conversation"] [data-message-role="user"] .mari-message-body {
  background:
    radial-gradient(circle at 0.9rem 1.05rem, var(--dw-hole) 0 3.5px, var(--dw-ring) 4px 6.5px, transparent 7px),
    var(--dw-rust-img) calc(0.9rem - 4px) calc(1.05rem + 5px) / 8px auto no-repeat,
    var(--dw-user-img) 0 0 / 512px repeat,
    var(--dw-tag-user);
}

/* grouped replies have a spacer instead of an avatar: keep the drop wire */
.mari-roleplay-message-row > .mari-roleplay-avatar-spacer {
  position: relative;
  align-self: stretch;
}
.mari-roleplay-message-row > .mari-roleplay-avatar-spacer::before {
  content: "";
  position: absolute;
  top: -1.35rem;
  bottom: -1.35rem;
  left: calc(50% - 3.5px);
  width: 7px;
  background: var(--dw-wire-v) center top / 7px 240px repeat-y;
  pointer-events: none;
}

/* swipe and regenerate: stamped on a little grey plate under the tag */
.mari-roleplay-message-row .ov-rpf--below {
  width: fit-content;
  margin-top: 0.3rem;
  padding: 0.1rem 0.55rem 0.1rem 0.9rem;
  background: var(--dw-user-img) 0 0 / 512px, var(--dw-tag-user);
  color: var(--dw-ink) !important;
  clip-path: polygon(0.5rem 0, 100% 0, 100% 100%, 0.5rem 100%, 0 calc(100% - 0.5rem), 0 0.5rem);
  filter: drop-shadow(0 1px 2px var(--dw-shadow));
}
.mari-roleplay-message-row .ov-rpf--below :is(button, span) {
  color: var(--dw-ink) !important;
  font-family: var(--dw-font-stamp);
}

/* ---------- 21. Ground strip: opaque, full width, wire on top ------------ */
.mari-chat-area .pointer-events-none.absolute.inset-x-0.bottom-0:has([data-mari-part="composer"]) {
  background:
    var(--dw-wire-h) left top / 240px 7px repeat-x,
    linear-gradient(to bottom, rgba(0, 0, 0, 0.12), transparent 0.8rem) 0 7px / 100% 1rem no-repeat,
    var(--dw-band);
  padding-top: 0.75rem;
}
.mari-chat-area .pointer-events-none.absolute.inset-x-0.bottom-0:has([data-mari-part="composer"]) [data-mari-part="composer"] {
  background: transparent;
  padding-top: 0 !important;
}
.mari-chat-area .pointer-events-none.absolute.inset-x-0.bottom-0:has([data-mari-part="composer"]) [data-mari-part="composer"]::after {
  display: none;
}
.mari-messages-scroll {
  padding-bottom: 8.25rem !important;
  scroll-padding-bottom: 8.25rem;
}
[data-mari-part="composer"] .mari-chat-input-box {
  background:
    radial-gradient(circle at 1.05rem 50%, var(--dw-hole) 0 4.5px, var(--dw-ring) 5px 8px, transparent 8.5px),
    var(--dw-grime-img) 0 0 / 7rem 3.5rem no-repeat,
    linear-gradient(90deg, color-mix(in srgb, var(--dw-tag-edge) 38%, transparent) 0 2.15rem, transparent 2.15rem),
    var(--dw-tag-img) 0 0 / 512px repeat,
    var(--dw-tag) !important;
  opacity: 1 !important;
}

/* ---------- 22. Galvanised sheet: spangle, lapped seams, rivets --------- */
[data-component="ChatSidebar"],
[data-component="RightPanelDesktop"],
.ov-gpane {
  background:
    linear-gradient(var(--dw-panel-wash), var(--dw-panel-wash)),
    var(--dw-metal-img) 0 0 / min(100%, 340px) auto repeat,
    var(--dw-metal-base) !important;
}
:root {
  --dw-panel-wash: color-mix(in srgb, #e6e2d8 18%, transparent);
  --dw-metal-base: #b3b1aa;
}
:root[data-theme="dark"] {
  --dw-panel-wash: transparent;
  --dw-metal-base: #1a1a1c;
}

/* ---------- 23. Game side panel: steel locker, party tags on a wire ------ */
.ov-gpane {
  --ov-text: var(--sidebar-foreground);
  border-left: 3px solid color-mix(in srgb, var(--dw-hole) 60%, transparent) !important;
  font-size: 0.875rem;
}
.ov-gpane__head {
  border-bottom: 0;
  background: var(--dw-wire-h) left bottom / 240px 7px repeat-x;
  padding-bottom: 0.85rem;
}
.ov-gpane__where b {
  font-family: var(--dw-font-stencil);
  font-weight: 800;
  font-size: 1.1rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}
.ov-gpane__head button {
  border-radius: 0;
}
.ov-gpane__tabs {
  gap: 0.3rem;
  border-bottom: 0;
  padding: 0.55rem 0.6rem;
}
.ov-gpane__tabs button {
  border-radius: 0;
  height: 1.9rem;
  padding: 0 0.55rem;
  font-family: var(--dw-font-stencil);
  font-weight: 800;
  font-size: 0.9rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--dw-ink);
  background:
    radial-gradient(circle at 4px 4px, #6a675f 0 1.5px, transparent 2px),
    radial-gradient(circle at calc(100% - 4px) 4px, #6a675f 0 1.5px, transparent 2px),
    var(--dw-plate-metal);
  border: 1px solid color-mix(in srgb, var(--dw-hole) 50%, transparent);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.18), 0 1px 0 rgba(0, 0, 0, 0.25);
}
.ov-gpane__tabs button.is-on {
  background: var(--dw-tag-img) 0 0 / 512px, var(--dw-tag);
  color: var(--dw-name);
  border-color: var(--dw-flag);
  box-shadow: inset 0 -3px 0 var(--dw-flag);
}
:root {
  --dw-plate-metal: linear-gradient(#c8c6be, #a9a79f);
}
:root[data-theme="dark"] {
  --dw-plate-metal: linear-gradient(#34332f, #24231f);
}
.ov-gpane__body.is-party,
.ov-gpane__body.is-inventory,
.ov-gpane__body.is-quests {
  position: relative;
  padding-left: 1.6rem;
  background: var(--dw-wire-v) 0.55rem 0 / 7px 240px repeat-y;
}
.ov-gpane__table {
  border-collapse: separate;
  border-spacing: 0 0.45rem;
  font-size: 0.875rem;
}
.ov-gpane__table thead th {
  border: 0;
  font-family: var(--dw-font-stamp);
  font-weight: 400;
  letter-spacing: 0.08em;
  color: var(--sidebar-foreground);
}
.ov-gpane__table tbody tr {
  filter: drop-shadow(0 2px 2px var(--dw-shadow));
}
.ov-gpane__table tbody td {
  border: 0 !important;
  color: var(--dw-ink);
  background: var(--dw-tag-img) 0 0 / 512px, var(--dw-tag);
  padding-top: 0.45rem;
  padding-bottom: 0.45rem;
}
.ov-gpane__table tbody td:first-child {
  position: relative;
  padding-left: 1.6rem;
  background:
    radial-gradient(circle at 0.75rem 50%, var(--dw-hole) 0 3px, var(--dw-ring) 3.5px 5.5px, transparent 6px),
    linear-gradient(90deg, color-mix(in srgb, var(--dw-tag-edge) 38%, transparent) 0 1.45rem, transparent 1.45rem),
    var(--dw-tag-img) 0 0 / 512px,
    var(--dw-tag);
  clip-path: polygon(0.7rem 0, 100% 0, 100% 100%, 0.7rem 100%, 0 calc(100% - 0.7rem), 0 0.7rem);
}
.ov-gpane__table tbody td:first-child::before {
  content: "";
  position: absolute;
  top: calc(50% - 3.5px);
  left: -1.1rem;
  width: 1.85rem;
  height: 7px;
  background: var(--dw-wire-h) left center / 240px 7px repeat-x;
}
.ov-gpane__table tbody tr.is-on td {
  background: var(--dw-tag-img) 0 0 / 512px, color-mix(in srgb, var(--dw-tag) 80%, var(--dw-flag));
}
.ov-gpane__table tbody tr.is-on td:last-child {
  box-shadow: inset -4px 0 0 var(--dw-flag);
}
.ov-gpane__who small,
.ov-gpane__na {
  color: var(--dw-ink-soft) !important;
}
.ov-gpane__av {
  border-radius: 999px;
  box-shadow: 0 0 0 2px var(--dw-ring);
}
.ov-gpane__meter {
  font-family: var(--dw-font-stamp);
}
.ov-gpane__meter i {
  border-radius: 0;
  height: 0.3rem;
  background: color-mix(in srgb, var(--dw-ink) 18%, transparent);
}
.ov-gpane__meter b {
  background: var(--dw-name);
}
.ov-gpane__label {
  font-family: var(--dw-font-stencil);
  font-weight: 800;
  font-size: 0.95rem;
  color: var(--sidebar-foreground);
}
.ov-gpane__stats span,
.ov-gpane__chips span {
  border-radius: 0;
  background: var(--dw-tag-img) 0 0 / 512px, var(--dw-tag);
  color: var(--dw-ink);
  border-color: var(--dw-tag-edge);
}
.ov-gpane__list li {
  border-bottom: 1px dashed color-mix(in srgb, var(--sidebar-foreground) 30%, transparent);
}
/* the map float and the Logs / Inventory / Combat buttons: square plates */
[data-mari-part="game-hud"] > *,
[data-mari-part="game-tools"] button {
  border-radius: 0 !important;
  font-family: var(--dw-font-ui);
}
[data-mari-part="game-tools"] button {
  background:
    radial-gradient(circle at 4px 4px, #6a675f 0 1.5px, transparent 2px),
    radial-gradient(circle at calc(100% - 4px) 4px, #6a675f 0 1.5px, transparent 2px),
    var(--dw-plate-metal) !important;
  color: var(--dw-ink) !important;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
/* the narration's inner panel: a painted stencil frame, not a dashed box */
[data-mari-part="message"][data-game-narration] .game-narration-prose {
  border: 0 !important;
  outline: 3px solid color-mix(in srgb, var(--dw-name) 55%, transparent);
  outline-offset: -3px;
  box-shadow:
    inset 0 0 0 6px transparent,
    inset 0 0 0 7px color-mix(in srgb, var(--dw-name) 22%, transparent) !important;
  padding: 0.9rem 1.1rem !important;
}

/* ---------- 24. Square every stock pill, toggle and select --------------- */
:is(input, select, textarea, [role="switch"], [role="tab"], [role="combobox"], .mari-chrome-control, .ov-chip, .ov-pill),
button:not([data-mari-part="avatar"] button):not(.mari-home-widget__drag-handle),
[role="switch"] > span,
[data-settings-switch-track], [data-settings-switch-thumb], .ov-switch, .ov-switch span {
  border-radius: 1px !important;
}
:is([role="switch"], [data-settings-switch-track], .ov-switch) {
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--dw-hole) 55%, transparent), inset 0 2px 2px rgba(0, 0, 0, 0.25);
}
:is([role="switch"] > span, [data-settings-switch-thumb], .ov-switch span) {
  background:
    repeating-linear-gradient(90deg, transparent 0 2px, rgba(0, 0, 0, 0.18) 2px 3px),
    linear-gradient(#e1ded6, #a8a59c) !important;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.45);
}
:is([role="switch"][aria-checked="true"], [data-settings-switch-track][data-checked], .ov-switch.is-on) {
  background: var(--primary) !important;
}
[data-component="ChatSidebar"] .mari-chrome-control--primary,
.ov-libpage__head button,
.ov-libpage__actions button {
  font-family: var(--dw-font-stencil);
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
/* page titles in the stencil, like every other heading */
.ov-settings__head h1,
.ov-libnav__title,
.ov-libpage__head h1 {
  font-family: var(--dw-font-stencil) !important;
  font-weight: 800 !important;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

/* ---------- 25. Toasts: a small tag, dark ink, a stencilled plate -------- */
[data-sonner-toast] {
  border-radius: 0 !important;
  border: 0 !important;
  background:
    radial-gradient(circle at 0.9rem 50%, var(--dw-hole) 0 4px, var(--dw-ring) 4.5px 7px, transparent 7.5px),
    linear-gradient(90deg, color-mix(in srgb, var(--dw-tag-edge) 38%, transparent) 0 1.85rem, transparent 1.85rem),
    var(--dw-tag-img) 0 0 / 512px,
    var(--dw-tag) !important;
  color: var(--dw-ink) !important;
  clip-path: polygon(0.9rem 0, 100% 0, 100% 100%, 0.9rem 100%, 0 calc(100% - 0.9rem), 0 0.9rem);
  padding-left: 2.4rem !important;
  box-shadow: none !important;
}
[data-sonner-toast] :is([data-title], [data-description], [data-content], div) {
  color: var(--dw-ink) !important;
}
[data-sonner-toast] [data-description] {
  color: var(--dw-ink-soft) !important;
  opacity: 1 !important;
}
[data-sonner-toast] [data-icon] {
  display: none;
}
[data-sonner-toast] :is([data-button], [data-cancel]) {
  border-radius: 0 !important;
  background: var(--dw-plate-metal) !important;
  color: var(--dw-ink) !important;
  font-family: var(--dw-font-stencil);
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  border: 1px solid color-mix(in srgb, var(--dw-hole) 50%, transparent) !important;
}
[data-sonner-toast] [data-close-button] {
  border-radius: 0 !important;
  background: var(--dw-tag) !important;
  color: var(--dw-ink) !important;
  border-color: var(--dw-tag-edge) !important;
  left: auto !important;
  right: 0.3rem !important;
  top: 0.3rem !important;
  transform: none !important;
}

/* ---------- 26. Ctrl+K: a big shipping tag on a string ------------------ */
[data-component="GlobalOmnibar"] > [data-component="GlobalOmnibar.Panel"] {
  border-radius: 1.5rem 1.5rem 2px 2px !important;
  corner-shape: bevel bevel square square;
  -webkit-mask:
    linear-gradient(135deg, transparent 1.05rem, #000 1.06rem) left top / 51% 3rem no-repeat,
    linear-gradient(225deg, transparent 1.05rem, #000 1.06rem) right top / 51% 3rem no-repeat,
    linear-gradient(#000, #000) left 3rem / 100% calc(100% - 3rem) no-repeat;
  mask:
    linear-gradient(135deg, transparent 1.05rem, #000 1.06rem) left top / 51% 3rem no-repeat,
    linear-gradient(225deg, transparent 1.05rem, #000 1.06rem) right top / 51% 3rem no-repeat,
    linear-gradient(#000, #000) left 3rem / 100% calc(100% - 3rem) no-repeat;
  background:
    radial-gradient(circle at 50% 1.25rem, var(--dw-hole) 0 5px, var(--dw-ring) 5.5px 9px, transparent 9.5px),
    linear-gradient(to top right, transparent calc(50% - 1.2px), #6b5a43 calc(50% - 1.2px) calc(50% + 1.2px), transparent calc(50% + 1.2px)) calc(50% - 1.1rem) 0 / 2.2rem 1.25rem no-repeat,
    linear-gradient(to bottom right, transparent calc(50% - 1.2px), #6b5a43 calc(50% - 1.2px) calc(50% + 1.2px), transparent calc(50% + 1.2px)) calc(50% + 1.1rem) 0 / 2.2rem 1.25rem no-repeat,
    radial-gradient(circle at 50% 1.25rem, color-mix(in srgb, var(--dw-tag-edge) 55%, transparent) 0 1.15rem, transparent 1.2rem),
    var(--dw-rust-img) calc(50% - 4px) 1.9rem / 10px auto no-repeat,
    var(--dw-stain-soft) right 5% bottom 13% / 6.5rem 6.5rem no-repeat,
    var(--dw-tag-img) 0 0 / 512px repeat,
    var(--dw-tag) !important;
  padding-top: 1.6rem !important;
  --card: var(--dw-tag);
  --foreground: var(--dw-ink);
  --muted-foreground: var(--dw-ink-soft);
  color: var(--dw-ink);
}
[data-component="GlobalOmnibar"] .rounded-md.border,
[data-component="GlobalOmnibar"] .rounded-lg.border {
  border-radius: 0 !important;
  border-color: color-mix(in srgb, #7a3b1e 55%, transparent) !important;
  background: color-mix(in srgb, #9c4f26 16%, var(--dw-tag)) !important;
  color: var(--dw-name) !important;
}
[data-component="GlobalOmnibar"] .rounded-md.border svg,
[data-component="GlobalOmnibar"] .rounded-lg.border svg {
  color: var(--dw-name) !important;
  stroke: currentColor;
}
[data-component="GlobalOmnibar"] .truncate {
  text-overflow: clip;
}

/* ---------- 27. Polish ------------------------------------------------- */
.mari-home-widget__drag-handle {
  top: 2.15rem !important;
  right: 0.45rem !important;
}
[data-mari-part="home-widget-title"] {
  line-height: 1.05;
  margin-bottom: 0.4rem;
}
[data-chat-row] .tabular-nums {
  font-family: var(--dw-font-ui);
  font-weight: 600;
  letter-spacing: 0;
  font-size: 0.75rem;
  white-space: nowrap;
  flex: none;
  min-width: 0 !important;
  width: auto !important;
}
[data-chat-row] span.block.truncate {
  font-size: 0.95rem;
}
:root[data-theme="dark"] [data-component="ChatSidebar"] .stagger-children::before {
  filter: brightness(1.15);
}

/* ---------- 28. Phones: a wider reading measure, drops instead of a frame */
@media (max-width: 767px) {
  :root {
    --mari-chat-font-size: 15.5px;
    --dw-strip: 1.6rem;
    --dw-eye-x: 0.8rem;
    --dw-cut: 0.9rem;
  }
  .mari-roleplay-message-row {
    padding-left: 0.8rem !important;
    padding-right: 0.8rem !important;
  }
  .mari-roleplay-message-row::before,
  .mari-roleplay-message-row::after {
    width: 5px;
    background-size: 5px 171px;
  }
  .mari-roleplay-message-row::before { left: 0.15rem; }
  .mari-roleplay-message-row::after { right: 0.15rem; }
  /* each tag hangs from its own drop: left for the cast, right for you */
  .mari-message-user.mari-roleplay-message-row::before,
  .mari-roleplay-message-row:not(.mari-message-user)::after {
    display: none;
  }
  .mari-roleplay-message-row .mari-message-body::before {
    left: -0.65rem;
    width: calc(0.65rem + var(--dw-eye-x));
    height: 5px;
    background-size: 240px 5px;
  }
  .mari-message-user.mari-roleplay-message-row .mari-message-body::before {
    left: auto;
    right: -0.65rem;
  }
  .mari-rp-bubble > div {
    padding: 0.65rem 0.8rem 0.8rem 1.95rem !important;
  }
  .mari-rp-bubble.mari-rp-bubble--user > div {
    padding: 0.65rem 1.95rem 0.8rem 0.8rem !important;
  }
  .mari-messages-scroll {
    padding-left: 0.35rem !important;
    padding-right: 0.35rem !important;
  }
}

[data-component="GlobalOmnibar"] ul.sm\:grid-cols-3 {
  grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr)) !important;
}
[data-component="GlobalOmnibar"] li.rounded-xl,
[data-component="GlobalOmnibar"] li.rounded-xl > button {
  border-radius: 0 !important;
}
[data-chat-row] span.block.truncate {
  font-size: 0.92rem;
  letter-spacing: -0.005em;
}

/* ==========================================================================
   ROUND 3
   ========================================================================== */
:root {
  --dw-stain-soft: url("theme:stain-soft.webp");
}
/* ---------- 29. Decals vary tag by tag --------------------------------- */
[data-mari-part="message"] {
  --dw-rust-w: calc(max(0, mod(var(--dw-i) * 5, 7) - 2) * 3px);
  --dw-rust-dy: calc(2px + mod(var(--dw-i) * 3, 5) * 1.5px);
  --dw-grime-l: var(--dw-grime-img) 0 calc(mod(var(--dw-i) * 2, 3) * 50%) / calc(max(0, mod(var(--dw-i) * 4, 5) - 1) * 2rem) auto no-repeat;
}

/* ---------- 30. Menus sit on a seam-free sheet ------------------------- */
[data-component="RightPanelDesktop"],
.ov-gpane {
  background:
    linear-gradient(var(--dw-panel-wash), var(--dw-panel-wash)),
    var(--dw-sheet-img) 0 0 / min(100%, 340px) auto repeat,
    var(--dw-metal-base) !important;
}

/* ---------- 31. Game: five tabs fit, icons clear the text, a calmer frame */
.ov-gpane__tabs {
  flex-wrap: wrap;
  gap: 0.25rem;
}
.ov-gpane__tabs button {
  padding: 0 0.45rem;
  font-size: 0.85rem;
  letter-spacing: 0.04em;
}
.ov-gpane__tabs button svg {
  display: none;
}
[data-mari-part="message"][data-game-narration] .game-narration-prose {
  padding: 2rem 1.1rem 0.9rem !important;
  outline: 2px solid color-mix(in srgb, var(--dw-ring) 55%, transparent);
  outline-offset: -2px;
  box-shadow: inset 0 0 0 5px transparent, inset 0 0 0 6px color-mix(in srgb, var(--dw-ring) 22%, transparent) !important;
}
[data-mari-part="game-hud"] > * {
  background:
    radial-gradient(circle at 4px 4px, #6a675f 0 1.5px, transparent 2px),
    radial-gradient(circle at calc(100% - 4px) 4px, #6a675f 0 1.5px, transparent 2px),
    radial-gradient(circle at 4px calc(100% - 4px), #6a675f 0 1.5px, transparent 2px),
    radial-gradient(circle at calc(100% - 4px) calc(100% - 4px), #6a675f 0 1.5px, transparent 2px),
    var(--dw-sheet-img) 0 0 / 240px auto,
    var(--dw-metal-base) !important;
  border: 1px solid color-mix(in srgb, var(--dw-hole) 55%, transparent) !important;
  box-shadow: 0 3px 8px var(--dw-shadow) !important;
}
[data-mari-part="game-hud"] .mari-game-narration-surface {
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
  border-radius: 0 !important;
  backdrop-filter: none !important;
}
[data-mari-part="game-hud"] .mari-game-narration-surface span {
  font-family: var(--dw-font-stamp);
  font-size: 0.8rem;
  color: var(--sidebar-foreground) !important;
}
[data-mari-part="game-hud"] .mari-game-narration-surface button {
  border-radius: 0 !important;
  background: var(--dw-plate-metal) !important;
  color: var(--dw-ink) !important;
  border: 1px solid color-mix(in srgb, var(--dw-hole) 50%, transparent) !important;
}

/* ---------- 32. The last pills, the last title ------------------------- */
.ov-seg,
.ov-seg button,
span.rounded-full.ring-1 {
  border-radius: 1px !important;
}
span.rounded-full.ring-1 {
  font-family: var(--dw-font-stamp);
  background: var(--dw-tag) !important;
  color: var(--dw-ink) !important;
}
.ov-gallery__head h1 {
  font-family: var(--dw-font-stencil) !important;
  font-weight: 800 !important;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

/* ==========================================================================
   FINAL POLISH
   ========================================================================== */
/* quieter colour on Home icons and placeholder portraits */
[data-mari-part="home-widget"] svg {
  color: var(--dw-name) !important;
  opacity: 0.85;
}
[data-mari-part="home-widget"] :is(img[src*="placeholder"], [data-mari-part="avatar-placeholder"]),
[data-mari-part="card-art"]:not(:has(img)) {
  filter: saturate(0.4) sepia(0.3);
}
